import{d as i,N as o,i as a,l as t}from"./chunks/framework.YjmuzLiw.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction","outline":"deep"},"headers":[],"relativePath":"en/excel/introduction.md","filePath":"en/excel/introduction.md","lastUpdated":1778907633000}'),n={name:"en/excel/introduction.md"};function l(r,e,s,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="spreadsheet" tabindex="-1">Spreadsheet <a class="header-anchor" href="#spreadsheet" aria-label="Permalink to &quot;Spreadsheet&quot;">​</a></h1><p><code>@norio-office/office-excel</code> is a Vue 3 spreadsheet component for embedding workbook-style editing into business systems. It provides workbook rendering, cell editing, toolbar controls, import/export, JSON snapshots, plain text extraction, optional collaboration hooks, and an instance API.</p><p>The component DOM/CSS class prefix is <code>norio-office-excel</code>.</p><h2 id="suitable-scenarios" tabindex="-1">Suitable Scenarios <a class="header-anchor" href="#suitable-scenarios" aria-label="Permalink to &quot;Suitable Scenarios&quot;">​</a></h2><ul><li>Embed online spreadsheet editing into a business system</li><li>Create, edit, save, and restore complete workbook snapshots</li><li>Import <code>.xlsx</code> / <code>.xlsm</code> files and export <code>.xlsx</code></li><li>Read JSON snapshots or plain-text two-dimensional arrays</li><li>Control editing, import, export, sheet management, image, chart, and formatting permissions</li><li>Reserve a collaboration integration layer while keeping the demo single-user by default</li></ul><h2 id="main-capabilities" tabindex="-1">Main Capabilities <a class="header-anchor" href="#main-capabilities" aria-label="Permalink to &quot;Main Capabilities&quot;">​</a></h2><ul><li>Workbook model: <code>v-model</code> binds a complete <code>OfficeExcelWorkbookSnapshot</code></li><li>Spreadsheet editing: cell selection, editing, sheet switching, copy, readonly mode</li><li>Configurable toolbar: <code>tabs</code> and <code>menu</code> modes with tab/command allowlists and blocklists</li><li>Permissions: disable import, export, editing, sheet management, images, charts, or formatting</li><li>Data IO: import Excel, export Excel, export/download JSON, serialize, external loading</li><li>Backgrounds: built-in solid/gradient backgrounds and business-provided background images</li><li>Collaboration hooks: optional Yjs document mirror and command envelope submission</li></ul><h2 id="reading-order" tabindex="-1">Reading Order <a class="header-anchor" href="#reading-order" aria-label="Permalink to &quot;Reading Order&quot;">​</a></h2><ol><li>Start with <a href="/en/excel/getting-started">Getting Started</a></li><li>If you need multi-user integration, read <a href="/en/excel/collaboration">Collaboration</a></li><li>Then read <a href="/en/excel/api">API</a></li><li>Finally check <a href="/en/excel/demo">Demo</a> and <a href="/en/excel/playground">Playground</a></li></ol>',9)])])}const u=i(n,[["render",l]]);export{h as __pageData,u as default};
